import { getMetaContent } from "helpers/meta_helpers"

export function signedDifferenceInDays(fromDate, toDate) {
  return Math.round((beginningOfDay(toDate) - beginningOfDay(fromDate)) / (1000 * 60 * 60 * 24))
}

export function beginningOfDay(date) {
  const { year, month, day } = datePartsInTimezone(date)
  return new Date(Date.UTC(year, month - 1, day))
}

export function sameYear(date, otherDate) {
  return datePartsInTimezone(date).year === datePartsInTimezone(otherDate).year
}

// The viewer's timezone. Prefer the `timezone` meta tag (derived from the
// timezone cookie the browser sets) so client day boundaries match the
// server's day grouping instead of following the browser's resolved timezone,
// which can differ in a PWA. Returns undefined when the tag is missing or
// invalid, so Intl falls back to the browser's own timezone.
export function timezone() {
  const name = getMetaContent("timezone")

  if (name !== timezoneCache.name) {
    timezoneCache = { name, value: validTimezone(name) }
  }

  return timezoneCache.value
}

let timezoneCache = {}

function validTimezone(name) {
  try {
    return name ? new Intl.DateTimeFormat("en-US", { timeZone: name }).resolvedOptions().timeZone : undefined
  } catch {
    return undefined
  }
}

function datePartsInTimezone(date) {
  return dateFormatter().formatToParts(date).reduce((parts, { type, value }) => {
    if (type !== "literal") parts[type] = parseInt(value, 10)
    return parts
  }, {})
}

let dateFormatterCache
let dateFormatterTimezone

function dateFormatter() {
  const currentTimezone = timezone()

  if (!dateFormatterCache || dateFormatterTimezone !== currentTimezone) {
    dateFormatterTimezone = currentTimezone
    dateFormatterCache = new Intl.DateTimeFormat("en-US", { year: "numeric", month: "2-digit", day: "2-digit", timeZone: currentTimezone })
  }

  return dateFormatterCache
}
