import { BridgeComponent } from "@hotwired/hotwire-native-bridge"

export default class extends BridgeComponent {
  static component = "stamp"
  static values = { scopeSelector: { type: String, default: "body" } }

  connect() {
    super.connect()

    if (this.#inScope) {
      this.notifyBridgeOfConnect()
      this.#observeStamp()
    }
  }

  disconnect() {
    super.disconnect()
    this.notifyBridgeOfDisconnect()
    this.stampObserver?.disconnect()
  }

  // The stamp's date is rendered in the browser, in the viewer's timezone, so
  // tell the bridge again once it's available.
  refresh() {
    if (this.#inScope) this.notifyBridgeOfConnect()
  }

  notifyBridgeOfConnect() {
    const bridgeElement = this.bridgeElement

    this.send("connect", {
      title: bridgeElement.title,
      description: bridgeElement.bridgeAttribute("description") ?? this.#localDate
    })
  }

  notifyBridgeOfDisconnect() {
    this.send("disconnect")
  }

  get #inScope() {
    return this.element.closest(this.scopeSelectorValue)
  }

  get #localDate() {
    return this.element.querySelector("time")?.textContent.trim()
  }

  #observeStamp() {
    this.stampObserver = new MutationObserver(() => {
      this.notifyBridgeOfConnect()
    })

    this.stampObserver.observe(this.element, {
      attributes: true
    })
  }
}
